import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth, createWorkspace, uniqueName } from './helpers';

test.describe(`anyone in the group: see the full history of expenses and payments`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`the history view lists every expense and settlement ordered by time, visible to all group members`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    await loginViaHash(pageA, 0);
    await loginViaHash(pageB, 1);
    await createWorkspace(pageA);
    await createWorkspace(pageB);

    const payer = uniqueName('payer');
    const friend = uniqueName('friend');
    const description = uniqueName('groceries');

    const addForm = pageA.getByTestId('add-expense-form');
    await addForm.getByTestId('field-description').fill(description);
    await addForm.getByTestId('field-amount').fill('30');
    await pageA.getByTestId('field-paid_by').fill(payer);
    await pageA.getByTestId('field-split_between').fill(`${payer},${friend}`);
    await pageA.getByTestId('action-add_expense').click();

    // Settlement is recorded strictly after the expense, so it must appear
    // above it once sorted by time (most recent first).
    const settleForm = pageA.getByTestId('settle-up-form');
    await settleForm.getByTestId('field-from').fill(friend);
    await settleForm.getByTestId('field-to').fill(payer);
    await settleForm.getByTestId('field-amount').fill('15');
    await pageA.getByTestId('action-record_settlement').click();

    // Both the expense and the settlement are visible to the OTHER group member.
    await expect(pageB.getByText(description)).toBeVisible({ timeout: 5_000 });
    const settlementRow = pageB.locator('[data-testid^="item-settlement-"]', { hasText: friend });
    await expect(settlementRow).toBeVisible({ timeout: 5_000 });

    // Ordered by time: the settlement (created after) appears before the
    // expense in the rendered history list.
    const historyTexts = await pageB
      .locator('[data-testid^="item-expense-"], [data-testid^="item-settlement-"]')
      .allTextContents();
    const expenseIdx = historyTexts.findIndex((t) => t.includes(description));
    const settlementIdx = historyTexts.findIndex((t) => t.includes('Settlement') && t.includes(friend));
    expect(expenseIdx).toBeGreaterThanOrEqual(0);
    expect(settlementIdx).toBeGreaterThanOrEqual(0);
    expect(settlementIdx).toBeLessThan(expenseIdx);

    await ctxA.close();
    await ctxB.close();
  });
});
